"""Local material atlas browser. It displays source pixels only from D: captures.
Git receives this generator and numeric region data, never the pixels or pages.
"""
import json,gzip,sqlite3,html,re,os
from pathlib import Path
from collections import defaultdict
R=Path('D:/Codex/sd-research');D=R/'repo/docs/SD-RESEARCH/data';O=R/'pictures/material-library';O.mkdir(parents=True,exist_ok=True)
def read(p):return json.loads(Path(p).read_text('utf-8-sig'))
def stem(p):return str(p).lower().replace('/','\\').split(':')[-1].rsplit('.',1)[0]
def safejson(x):return json.dumps(x,separators=(',',':')).replace('<','\\u003c')
native=[t for t in read(R/'data/native-textures.json')if t['tier']=='sd'];aliases=defaultdict(list)
for t in native:
 for p in t['aliases']:aliases[stem(p)].append(t['id'])
review={stem(a['texturePath']):a['observedContents']for a in read(D/'lpw-owner-material-sheets.json')}
models={m['id']:m.get('name',m['id'])for m in read(R/'data/lpw-manifest.json')};caps={};emitters=defaultdict(list)
with gzip.open(D/'effect-atlases-sd.jsonl.gz','rt',encoding='utf-8')as f:
 for l in f:
  e=json.loads(l);mid=e['modelId']
  if mid not in caps:
   p=R/'captures/models'/mid/'capture.json';caps[mid]=read(p)if p.exists()else{}
  resolutions=caps[mid].get('textureResolution',[]);tid=next((s['id']for s in resolutions if stem(s['name'])==stem(e['texturePath'])),None)
  if tid:emitters[tid].append(e)
db=sqlite3.connect(R/'data/uv-library.sqlite');groups=defaultdict(list)
for (payload,)in db.execute('SELECT payload FROM regions'):
 r=json.loads(payload);tid=r['resolvedTextureId']
 if tid:groups[tid].append({k:r[k]for k in ['modelId','modelPath','partId','geoset1','component1','texturePath','textureFlags','uvSet','uvTriangles','label','semanticStatus','materialTags','meshTriangles','sampledCoverage64','tagScope','authoredColour','materialLayers','geosetAlphaAtSample','visibleAtSample','textureIdentityEvidence','textureContentHash','clampedEdgeFootprintOmitted']})
db.close();masters={}
for p in (R/'captures/textures').glob('*.webp.json'):
 m=read(p)
 if 'id' not in m:continue
 if m['id'].startswith('native-hd-')or m['id'].startswith('native-de-'):continue
 masters[m['id']]=m
ids=set(masters)|set(groups)|set(emitters);index=[]
css='''body{margin:0;background:#10161c;color:#e5eaf0;font:16px/1.5 system-ui}main{max-width:1500px;margin:auto;padding:28px}a{color:#8dd6fb}input,select,button{font:inherit;background:#26333f;color:inherit;border:1px solid #637686;padding:8px;border-radius:4px}input{width:min(700px,90%)}.split{display:grid;grid-template-columns:minmax(320px,1fr) minmax(340px,1fr);gap:24px}.paint{position:sticky;top:16px;align-self:start}canvas{width:100%;max-height:80vh;object-fit:contain;image-rendering:auto;background:repeating-conic-gradient(#202830 0% 25%,#29333e 0% 50%) 50%/20px 20px}#rows{max-height:65vh;overflow:auto}.row{padding:9px;border-bottom:1px solid #344351;cursor:pointer}.row:hover,.selected{background:#334b60}.muted{color:#adbac7;font-size:14px}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:15px}.card{background:#1d2731;padding:14px;border-radius:7px}.card img{width:100%;height:180px;object-fit:contain}.tag{display:inline-block;background:#35434f;padding:2px 7px;margin:2px;font-size:13px}pre{white-space:pre-wrap;font-size:12px}@media(max-width:850px){.split{display:block}.paint{position:static}#rows{max-height:45vh}}'''
(O/'style.css').write_text(css,'utf-8')
js=r'''
const data=JSON.parse(document.getElementById('data').textContent),canvas=document.getElementById('paint'),ctx=canvas.getContext('2d'),picture=new Image();let chosen=-1,mode='mesh';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
picture.onload=()=>{canvas.width=picture.naturalWidth;canvas.height=picture.naturalHeight;paint()};picture.src=data.image;
function entries(){return mode==='mesh'?data.regions:data.emitters}
function paint(){ctx.clearRect(0,0,canvas.width,canvas.height);if(picture.complete)ctx.drawImage(picture,0,0);if(chosen<0)return;const r=entries()[chosen];ctx.strokeStyle='#49ffff';ctx.lineWidth=Math.max(canvas.width/600,0.6);ctx.fillStyle='#00ffff22';if(mode==='mesh'){for(const t of r.uvTriangles){const xs=[t[0],t[2],t[4]],ys=[t[1],t[3],t[5]],a=r.textureFlags&1?Math.floor(Math.min(...xs)):0,b=r.textureFlags&1?Math.floor(Math.max(...xs)):0,c=r.textureFlags&2?Math.floor(Math.min(...ys)):0,d=r.textureFlags&2?Math.floor(Math.max(...ys)):0;if((b-a+1)*(d-c+1)>256)continue;for(let x=a;x<=b;x++)for(let y=c;y<=d;y++){ctx.beginPath();for(let k=0;k<3;k++){const u=(xs[k]-x)*canvas.width,v=(ys[k]-y)*canvas.height;k?ctx.lineTo(u,v):ctx.moveTo(u,v)}ctx.closePath();ctx.fill();ctx.stroke()}}}else{for(const cell of r.cells){const[a,b,c,d]=cell.uvBounds;ctx.strokeRect(a*canvas.width,b*canvas.height,(c-a)*canvas.width,(d-b)*canvas.height)}}}
function rows(){const q=document.getElementById('q').value.toLowerCase(),list=entries(),host=document.getElementById('rows');host.innerHTML='';let count=0;list.forEach((r,i)=>{const name=data.names[r.modelId]||r.modelPath||r.modelId,title=mode==='mesh'?(r.label||`g${r.geoset1}:c${r.component1} — interpretation pending`):r.name;if(!(title+' '+name+' '+JSON.stringify(r.materialTags||[])).toLowerCase().includes(q))return;count++;const row=document.createElement('div');row.className='row'+(i===chosen?' selected':'');row.innerHTML=`<strong>${esc(title)}</strong><br><span class="muted">${esc(name)}${mode==='mesh'?` · g${r.geoset1}:c${r.component1} · ${r.meshTriangles} triangles · UV set ${r.uvSet}`:` · ${r.rows}×${r.columns} atlas · ${esc(r.filterName)}`}</span>`;row.onclick=()=>{chosen=i;paint();rows();document.getElementById('detail').innerHTML=`<p><a href="../../captures/models/${encodeURIComponent(r.modelId)}/index.html">Open model pictures and part context</a></p><p>${mode==='mesh'?esc((r.materialTags||[]).join(', ')||'Material interpretation pending')+' · '+esc(r.semanticStatus):'Authored particle atlas cells'}</p><p class="muted">Cyan marks the actual mapped triangles. Model tint, team colour and lighting can change the source paint.</p><details><summary>Measurements and colour controls</summary><pre>${esc(JSON.stringify(mode==='mesh'?{part:r.partId,label:r.label,semanticStatus:r.semanticStatus,materials:r.materialTags,materialTagScope:r.tagScope,authoredColour:r.authoredColour,geosetAlphaAtSample:r.geosetAlphaAtSample,visibleAtSample:r.visibleAtSample,uvSet:r.uvSet,sheetPixelShare64:r.sampledCoverage64,clampedEdgeFootprintOmitted:r.clampedEdgeFootprintOmitted,textureIdentity:r.textureIdentityEvidence,warning:'64×64 approximate union; exact UV triangles are overlaid. Appearance can also include authored tint, team colour and lighting.'}:r,null,2))}</pre></details>`};host.appendChild(row)});document.getElementById('count').textContent=`${count} matching ${mode==='mesh'?'component regions':'emitters'}`}
document.getElementById('q').oninput=rows;document.getElementById('mode').onchange=e=>{mode=e.target.value;chosen=-1;rows();paint()};document.getElementById('clear').onclick=()=>{chosen=-1;paint();rows()};rows();
'''
(O/'atlas.js').write_text(js,'utf-8')
for n,tid in enumerate(sorted(ids)):
 m=masters.get(tid)
 if not m:continue
 regions=groups.get(tid,[]);em=emitters.get(tid,[]);name=m.get('path',tid);notes=review.get(stem(name),[]);image=R/'captures/textures'/m.get('previewFile',tid+'.webp')
 if not image.exists():image=R/'captures/textures'/(tid+'.webp')
 if not image.exists():continue
 data={'id':tid,'image':os.path.relpath(image,O).replace('\\','/'),'regions':regions,'emitters':em,'names':{r['modelId']:models.get(r['modelId'],r.get('modelPath',r['modelId']))for r in regions+em}}
 title=html.escape(name);tags=''.join('<span class="tag">'+html.escape(s)+'</span>'for s in notes);doc=f'''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{title}</title><link rel="stylesheet" href="style.css"><main><p><a href="index.html">Material library</a> · <a href="../index.html">Picture study</a></p><h1>{title}</h1><p>{m.get('width')} × {m.get('height')} source pixels · {len(regions)} component regions · {len(em)} particle emitters</p><p>{tags}</p><p class="muted">Whole-sheet appearance notes do not label every pixel. Select an actual part or emitter to see its authored UV region. Unnamed regions are measured evidence awaiting interpretation; no safe rectangles are guessed.</p><div class="split"><div class="paint"><canvas id="paint"></canvas><button id="clear">Hide UV overlay</button></div><section><select id="mode"><option value="mesh">Model parts</option><option value="emitter">Particle atlas use</option></select><p><input id="q" placeholder="Find a part, model or material"></p><p id="count"></p><div id="rows"></div><div id="detail"></div></section></div><details><summary>Whole-sheet measured colour and alpha</summary><pre>{html.escape(json.dumps(m.get('pixelStats',{}),indent=2))}</pre></details><script id="data" type="application/json">{safejson(data)}</script><script src="atlas.js"></script></main>'''
 (O/(tid+'.html')).write_text(doc,'utf-8');index.append({'id':tid,'name':name,'regions':len(regions),'emitters':len(em),'named':sum(bool(r['label'])for r in regions),'notes':notes,'image':data['image']})
 if(n+1)%1000==0:print(json.dumps({'pages':n+1}),flush=True)
indexjs=r'''const all=JSON.parse(document.getElementById('data').textContent);let page=0;const q=document.getElementById('q'),used=document.getElementById('used');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function show(){const a=all.filter(x=>(!used.checked||x.regions||x.emitters)&&(x.name+' '+x.notes.join(' ')).toLowerCase().includes(q.value.toLowerCase()));page=Math.max(0,Math.min(page,Math.ceil(a.length/60)-1));document.getElementById('count').textContent=`${a.length} sheets · page ${page+1} / ${Math.max(1,Math.ceil(a.length/60))}`;document.getElementById('cards').innerHTML=a.slice(page*60,page*60+60).map(x=>`<a class="card" href="${x.id}.html"><img loading="lazy" src="${x.image}"><strong>${esc(x.name)}</strong><br>${x.regions} regions, ${x.named} named; ${x.emitters} emitters<br><span class="muted">${esc(x.notes.join(', '))}</span></a>`).join('')}q.oninput=used.onchange=()=>{page=0;show()};document.getElementById('prev').onclick=()=>{page--;show()};document.getElementById('next').onclick=()=>{page++;show()};show();'''
page=f'''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>SD material library</title><link rel="stylesheet" href="style.css"><main><a href="../index.html">Picture study</a><h1>SD texture regions and their real uses</h1><p>Every native SD sheet is included, plus resolved custom sheets used by the studied models. Search by observed whole-sheet material or by path; open a sheet to select exact component UV regions and particle atlas cells. The semantic study is unfinished: named regions and measured unnamed regions remain visibly distinct.</p><input id="q" placeholder="Try gold, bone, cloth, infernalcannon, inventory"><p><label><input id="used" type="checkbox" style="width:auto"> Only sheets with measured mesh or emitter use</label></p><button id="prev">Previous</button> <button id="next">Next</button><p id="count"></p><div id="cards" class="cards"></div><script id="data" type="application/json">{safejson(index)}</script><script>{indexjs}</script></main>'''
(O/'index.html').write_text(page,'utf-8');(D/'material-gallery-coverage.json').write_text(json.dumps({'pages':len(index),'regions':sum(x['regions']for x in index),'emitters':sum(x['emitters']for x in index),'namedRegions':sum(x['named']for x in index)},indent=2));print('done',len(index))
